    s.addText("11 Industries × 6 Agent Types: A Taxonomy of Enterprise Gen AI", {
      x: 0.5, y: 0.3, w: 9, h: 0.65,
      fontSize: 24, fontFace: "Arial Black", color: C.darkText, bold: true, margin: 0,
    });
    s.addText("1,001 use cases organized at the intersection of industry verticals and agent types", {
      x: 0.5, y: 0.95, w: 9, h: 0.3,
      fontSize: 12, fontFace: "Calibri", color: C.mutedText, italic: true,
    });

    const industries = [
      "Automotive & Logistics",
      "Business & Prof. Services",
      "Financial Services",
      "Healthcare & Life Sciences",
      "Hospitality & Travel",
      "Manufacturing & Industrial",
      "Media, Marketing & Gaming",
      "Public Sector & Nonprofits",
      "Retail",
      "Technology",
      "Telecommunications",
    ];
    const agentTypes = ["Customer", "Employee", "Creative", "Code", "Data", "Security"];

    // Column shading: Customer & Employee = dominant (slightly darker)
    const domFill = "DBEAFE";   // blue-100
    const emgFill = "EFF6FF";   // blue-50
