      rowH: 0.32,
    });

    // Legend
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: 5.0, w: 0.25, h: 0.18,
      fill: { color: domFill },
    });
    s.addText("Most common agent types (Customer, Employee)", {
      x: 0.85, y: 4.97, w: 3.5, h: 0.25,
      fontSize: 9, fontFace: "Calibri", color: C.mutedText, margin: 0,
