    const cols = [
      {
        icon: icHeadset, iconBg: C.primaryBlue,
        title: "Conversational\nCustomer Agents",
        desc: "The most visible entry point — AI-powered virtual assistants handle customer queries, reduce wait times, and lower human agent workloads.",
