const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// ── Color Palette (Enterprise Cloud AI) ──────────────────────────────
const C = {
  darkBg: "0D1B3E",
  primaryBlue: "1A56DB",
  skyBlue: "0EA5E9",
  emerald: "10B981",
  amber: "F59E0B",
  violet: "7C3AED",
  teal: "0D9488",
  lightBg: "F8FAFC",
  white: "FFFFFF",
  darkText: "0F172A",
  bodyText: "334155",
  mutedText: "64748B",
  lightBorder: "E2E8F0",
  tableAlt: "F1F5F9",
  highlight: "DBEAFE",
};

// ── Factory functions (avoid option-object reuse pitfall) ─────────────
const mkShadow = () => ({
  type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.1,
});

// ── Icon rendering ───────────────────────────────────────────────────
function renderIconSvg(IconComponent, color, size) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}
async function iconToPng(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const buf = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + buf.toString("base64");
}

// ── Main ─────────────────────────────────────────────────────────────
async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Google Cloud";
  pres.title = "1,001 Real-World Gen AI Use Cases from Google Cloud Customers";

  // Pre-render icons
  const { FaHeadset, FaUsers, FaPalette } = require("react-icons/fa");
  const icHeadset = await iconToPng(FaHeadset, "#FFFFFF");
  const icUsers   = await iconToPng(FaUsers, "#FFFFFF");
  const icPalette = await iconToPng(FaPalette, "#FFFFFF");

  // ═══════════════════════════════════════════════════════════════════
  // SLIDE 1 — TITLE / COVER
  // ═══════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.darkBg };

    // Top accent strip
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.skyBlue },
    });

    // Title
    s.addText("1,001 Real-World Gen AI\nUse Cases from\nGoogle Cloud Customers", {
      x: 0.8, y: 1.0, w: 8.4, h: 2.2,
      fontSize: 38, fontFace: "Arial Black",
      color: C.white, bold: true, align: "left", valign: "top", margin: 0,
    });

    // Key stats
    s.addText([
      { text: "11 Industries", options: { bold: true, color: C.skyBlue, fontSize: 16 } },
      { text: "  |  ", options: { color: C.mutedText, fontSize: 16 } },
      { text: "6 Agent Types", options: { bold: true, color: C.skyBlue, fontSize: 16 } },
      { text: "  |  ", options: { color: C.mutedText, fontSize: 16 } },
      { text: "Updated October 2025", options: { color: C.mutedText, fontSize: 16 } },
    ], {
      x: 0.8, y: 3.3, w: 8.4, h: 0.4, fontFace: "Calibri",
    });

    // Growth note
    s.addText("10× growth from the original 101 entries published at Cloud Next ‘24", {
      x: 0.8, y: 3.8, w: 8.4, h: 0.35,
      fontSize: 14, fontFace: "Calibri", color: C.mutedText, italic: true,
    });

    // Source
    s.addText("Source: Google Cloud Blog — “1,001 real-world gen AI use cases from the world’s leading organizations”", {
      x: 0.8, y: 4.9, w: 8.4, h: 0.3,
      fontSize: 10, fontFace: "Calibri", color: C.mutedText,
    });
  }

  // ═══════════════════════════════════════════════════════════════════
  // SLIDE 2 — GROWTH TRAJECTORY
  // ═══════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };

    // Title
    s.addText("From 101 to 1,001: Gen AI Adoption Grew 10× in 18 Months", {
      x: 0.5, y: 0.3, w: 9, h: 0.7,
      fontSize: 26, fontFace: "Arial Black", color: C.darkText, bold: true, margin: 0,
    });

    // ── Left card: April 2024 ──
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 1.5, w: 3.4, h: 2.6,
      fill: { color: C.white }, shadow: mkShadow(),
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 1.5, w: 0.06, h: 2.6,
      fill: { color: C.primaryBlue },
    });
    s.addText("April 2024", {
      x: 1.0, y: 1.65, w: 2.8, h: 0.3,
      fontSize: 13, fontFace: "Calibri", color: C.mutedText, align: "center", margin: 0,
    });
    s.addText("101", {
      x: 1.0, y: 2.0, w: 2.8, h: 0.85,
      fontSize: 56, fontFace: "Arial Black", color: C.primaryBlue,
      bold: true, align: "center", valign: "middle", margin: 0,
    });
    s.addText("Use Cases", {
      x: 1.0, y: 2.85, w: 2.8, h: 0.3,
      fontSize: 14, fontFace: "Calibri", color: C.bodyText, align: "center", margin: 0,
    });
    s.addText("Cloud Next ‘24", {
      x: 1.0, y: 3.15, w: 2.8, h: 0.3,
      fontSize: 12, fontFace: "Calibri", color: C.mutedText, align: "center", margin: 0,
    });

    // ── 10× callout (circle) ──
    s.addShape(pres.shapes.OVAL, {
      x: 4.25, y: 2.2, w: 1.0, h: 1.0,
      fill: { color: C.emerald },
    });
    s.addText("10×", {
      x: 4.25, y: 2.3, w: 1.0, h: 0.8,
      fontSize: 24, fontFace: "Arial Black", color: C.white,
      bold: true, align: "center", valign: "middle", margin: 0,
    });

    // ── Right card: October 2025 ──
    s.addShape(pres.shapes.RECTANGLE, {
      x: 5.5, y: 1.5, w: 3.8, h: 2.6,
      fill: { color: C.darkBg }, shadow: mkShadow(),
