um: \"3\",\n        title: \"Measurable ROI is achievable within months\",\n        note: \"500% ROI (Mercari), 30% workload reduction (LUXGEN), 10,000+ hours saved annually (Toyota).\",\n      },\n      {\n        num: \"4\",\n        title: \"Creative and code agents are emerging fast\",\n        note: \"Virgin Voyages, Figma, and PODS demonstrate multimodal creative production at enterprise scale.\",\n      },\n      {\n        num: \"5\",\n        title: \"Early movers gain compounding advantages\",\n        note: \"10× growth in 18 months, with 400 new entries in the latest update alone — the pace is accelerating.\",\n      },\n    ];\n\n    const startY = 1.2;\n    const itemH = 0.78;\n    const numX = 0.8;\n    const textX = 1.5;\n\n    takeaways.forEach((t, i) => {\n      const iy = startY + i * itemH;\n\n      // Number badge\n      s.addShape(pres.shapes.OVAL, {\n        x: numX, y: iy + 0.05, w: 0.4, h: 0.4,\n        fill: { color: C.skyBlue },\n      });\n      s.addText(t.num, {\n        x: numX, y: iy + 0.05, w: 0.4, h: 0.4,\n        fontSize: 16, fontFace: \"Arial Black\", color: C.white,\n        bold: true, align: \"center\", valign: \"middle\", margin: 0,\n      });\n\n      // Title\n      s.addText(t.title, {\n        x: textX, y: iy, w: 7.8, h: 0.35,\n        fontSize: 15, fontFace: \"Calibri\", color: C.white, bold: true, align: \"left\", margin: 0,\n      });\n\n      // Note\n      s.addText(t.note, {\n        x: textX, y: iy + 0.35, w: 7.8, h: 0.35,\n        fontSize: 11, fontFace: \"Calibri\", color: C.mutedText, align: \"left\", margin: 0,\n      });\n    });\n\n    // Closing line\n    s.addText(\"Source: Google Cloud Blog — “1,001 real-world gen AI use cases from the world’s leading organizations” (October 2025)\", {\n      x: 0.8, y: 5.15, w: 8.4, h: 0.25,\n      fontSize: 9, fontFace: \"Calibri\", color: C.mutedText,\n    });\n  }\n\n  // ── Write output ───────────────────────────────────────────────────\n  await pres.writeFile({ fileName: \"/app/output/final_deck.pptx\" });\n  console.log(\"DONE: /app/output/final_deck.pptx\");\n}\n\nmain().catch(err => { console.error(err); process.exit(1); });\n", "numLines": 597, "startLine": 1, "totalLines": 597}}

