const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// ── Color Palette (Enterprise Cloud AI) ──────────────────────────────
const C = {
  darkBg: "0D1B3E",
  primaryBlue: "1A56DB",
  skyBlue: "0EA5E9",
  emerald: "10B981",
  amber: "F59E0B",
  violet: "7C3AED",
  teal: "0D9488",
  lightBg: "F8FAFC",
  white: "FFFFFF",
  darkText: "0F172A",
  bodyText: "334155",
  mutedText: "64748B",
  lightBorder: "E2E8F0",
  tableAlt: "F1F5F9",
  highlight: "DBEAFE",
};

// ── Factory functions (avoid option-object reuse pitfall) ─────────────
const mkShadow = () => ({
  type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity: 0.1,
});

// ── Icon rendering ───────────────────────────────────────────────────
function renderIconSvg(IconComponent, color, size) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}
async function iconToPng(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const buf = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + buf.toString("base64");
}

// ── Main ─────────────────────────────────────────────────────────────
async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "Google Cloud";
  pres.title = "1,001 Real-World Gen AI Use Cases from Google Cloud Customers";

  // Pre-render icons
  const { FaHeadset, FaUsers, FaPalette } = require("react-icons/fa");
  const icHeadset = await iconToPng(FaHeadset, "#FFFFFF");
  const icUsers   = await iconToPng(FaUsers, "#FFFFFF");
  const icPalette = await iconToPng(FaPalette, "#FFFFFF");

  // ═══════════════════════════════════════════════════════════════════
  // SLIDE 1 — TITLE / COVER
  // ═══════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.darkBg };

    // Top accent strip
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.skyBlue },
    });

    // Title
    s.addText("1,001 Real-World Gen AI\nUse Cases from\nGoogle Cloud Customers", {
      x: 0.8, y: 1.0, w: 8.4, h: 2.2,
      fontSize: 38, fontFace: "Arial Black",
      color: C.white, bold: true, align: "left", valign: "top", margin: 0,
    });

    // Key stats
    s.addText([
      { text: "11 Industries", options: { bold: true, color: C.skyBlue, fontSize: 16 } },
      { text: "  |  ", options: { color: C.mutedText, fontSize: 16 } },
      { text: "6 Agent Types", options: { bold: true, color: C.skyBlue, fontSize: 16 } },
      { text: "  |  ", options: { color: C.mutedText, fontSize: 16 } },
      { text: "Updated October 2025", options: { color: C.mutedText, fontSize: 16 } },
    ], {
      x: 0.8, y: 3.3, w: 8.4, h: 0.4, fontFace: "Calibri",
    });

    // Growth note
    s.addText("10× growth from the original 101 entries published at Cloud Next ‘24", {
      x: 0.8, y: 3.8, w: 8.4, h: 0.35,
      fontSize: 14, fontFace: "Calibri", color: C.mutedText, italic: true,
    });

    // Source
    s.addText("Source: Google Cloud Blog — “1,001 real-world gen AI use cases from the world’s leading organizations”", {
      x: 0.8, y: 4.9, w: 8.4, h: 0.3,
      fontSize: 10, fontFace: "Calibri", color: C.mutedText,
    });
  }

  // ═══════════════════════════════════════════════════════════════════
  // SLIDE 2 — GROWTH TRAJECTORY
  // ═══════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };

    // Title
    s.addText("From 101 to 1,001: Gen AI Adoption Grew 10× in 18 Months", {
      x: 0.5, y: 0.3, w: 9, h: 0.7,
      fontSize: 26, fontFace: "Arial Black", color: C.darkText, bold: true, margin: 0,
    });

    // ── Left card: April 2024 ──
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 1.5, w: 3.4, h: 2.6,
      fill: { color: C.white }, shadow: mkShadow(),
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.7, y: 1.5, w: 0.06, h: 2.6,
      fill: { color: C.primaryBlue },
    });
    s.addText("April 2024", {
      x: 1.0, y: 1.65, w: 2.8, h: 0.3,
      fontSize: 13, fontFace: "Calibri", color: C.mutedText, align: "center", margin: 0,
    });
    s.addText("101", {
      x: 1.0, y: 2.0, w: 2.8, h: 0.85,
      fontSize: 56, fontFace: "Arial Black", color: C.primaryBlue,
      bold: true, align: "center", valign: "middle", margin: 0,
    });
    s.addText("Use Cases", {
      x: 1.0, y: 2.85, w: 2.8, h: 0.3,
      fontSize: 14, fontFace: "Calibri", color: C.bodyText, align: "center", margin: 0,
    });
    s.addText("Cloud Next ‘24", {
      x: 1.0, y: 3.15, w: 2.8, h: 0.3,
      fontSize: 12, fontFace: "Calibri", color: C.mutedText, align: "center", margin: 0,
    });

    // ── 10× callout (circle) ──
    s.addShape(pres.shapes.OVAL, {
      x: 4.25, y: 2.2, w: 1.0, h: 1.0,
      fill: { color: C.emerald },
    });
    s.addText("10×", {
      x: 4.25, y: 2.3, w: 1.0, h: 0.8,
      fontSize: 24, fontFace: "Arial Black", color: C.white,
      bold: true, align: "center", valign: "middle", margin: 0,
    });

    // ── Right card: October 2025 ──
    s.addShape(pres.shapes.RECTANGLE, {
      x: 5.5, y: 1.5, w: 3.8, h: 2.6,
      fill: { color: C.darkBg }, shadow: mkShadow(),
    });
    s.addText("October 2025", {
      x: 5.8, y: 1.65, w: 3.2, h: 0.3,
      fontSize: 13, fontFace: "Calibri", color: C.skyBlue, align: "center", margin: 0,
    });
    s.addText("1,001", {
      x: 5.8, y: 2.0, w: 3.2, h: 0.85,
      fontSize: 56, fontFace: "Arial Black", color: C.white,
      bold: true, align: "center", valign: "middle", margin: 0,
    });
    s.addText("Use Cases", {
      x: 5.8, y: 2.85, w: 3.2, h: 0.3,
      fontSize: 14, fontFace: "Calibri", color: C.white, align: "center", margin: 0,
    });
    s.addText("400 new entries in latest update", {
      x: 5.8, y: 3.15, w: 3.2, h: 0.3,
      fontSize: 12, fontFace: "Calibri", color: C.skyBlue, align: "center", margin: 0,
    });

    // Bottom insight
    s.addText("Enterprise gen AI deployment is still in its early exponential phase — the list still only scratches the surface of what is becoming possible.", {
      x: 0.7, y: 4.5, w: 8.6, h: 0.5,
      fontSize: 11, fontFace: "Calibri", color: C.mutedText, italic: true,
    });
  }

  // ═══════════════════════════════════════════════════════════════════
  // SLIDE 3 — INDUSTRY × AGENT TAXONOMY
  // ═══════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };

    s.addText("11 Industries × 6 Agent Types: A Taxonomy of Enterprise Gen AI", {
      x: 0.5, y: 0.3, w: 9, h: 0.65,
      fontSize: 24, fontFace: "Arial Black", color: C.darkText, bold: true, margin: 0,
    });
    s.addText("1,001 use cases organized at the intersection of industry verticals and agent types", {
      x: 0.5, y: 0.95, w: 9, h: 0.3,
      fontSize: 12, fontFace: "Calibri", color: C.mutedText, italic: true,
    });

    const industries = [
      "Automotive & Logistics",
      "Business & Prof. Services",
      "Financial Services",
      "Healthcare & Life Sciences",
      "Hospitality & Travel",
      "Manufacturing & Industrial",
      "Media, Marketing & Gaming",
      "Public Sector & Nonprofits",
      "Retail",
      "Technology",
      "Telecommunications",
    ];
    const agentTypes = ["Customer", "Employee", "Creative", "Code", "Data", "Security"];

    // Column shading: Customer & Employee = dominant (slightly darker)
    const domFill = "DBEAFE";   // blue-100
    const emgFill = "EFF6FF";   // blue-50
    const autoDomFill = "BFDBFE"; // blue-200
    const autoEmgFill = "DBEAFE"; // blue-100
    const isDominant = [true, true, false, false, false, false];

    const headerRow = [
      { text: "Industry", options: { fill: { color: C.darkBg }, color: C.white, bold: true, fontSize: 8, align: "left", valign: "middle" } },
      ...agentTypes.map(at => ({
        text: at,
        options: { fill: { color: C.darkBg }, color: C.white, bold: true, fontSize: 7.5, align: "center", valign: "middle" },
      })),
    ];

    const dataRows = industries.map((ind, i) => {
      const isAuto = (i === 0);
      const rowBg = isAuto ? C.highlight : (i % 2 === 0 ? C.white : C.tableAlt);
      const indOpts = {
        fill: { color: rowBg },
        color: isAuto ? C.primaryBlue : C.darkText,
        bold: isAuto,
        fontSize: 7.5,
        align: "left",
        valign: "middle",
      };
      const cells = agentTypes.map((_, j) => {
        const cellFill = isAuto
          ? (isDominant[j] ? autoDomFill : autoEmgFill)
          : (isDominant[j] ? domFill : emgFill);
        return {
          text: "",
          options: { fill: { color: cellFill }, fontSize: 7, align: "center", valign: "middle" },
        };
      });
      return [{ text: ind, options: indOpts }, ...cells];
    });

    s.addTable([headerRow, ...dataRows], {
      x: 0.5, y: 1.4, w: 9,
      colW: [2.3, 1.12, 1.12, 1.12, 1.12, 1.12, 1.12],
      border: { pt: 0.5, color: C.lightBorder },
      rowH: 0.32,
    });

    // Legend
    s.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y: 5.0, w: 0.25, h: 0.18,
      fill: { color: domFill },
    });
    s.addText("Most common agent types (Customer, Employee)", {
      x: 0.85, y: 4.97, w: 3.5, h: 0.25,
      fontSize: 9, fontFace: "Calibri", color: C.mutedText, margin: 0,
    });
    s.addShape(pres.shapes.RECTANGLE, {
      x: 4.5, y: 5.0, w: 0.25, h: 0.18,
      fill: { color: emgFill },
    });
    s.addText("Emerging agent types (Creative, Code, Data, Security)", {
      x: 4.85, y: 4.97, w: 4.5, h: 0.25,
      fontSize: 9, fontFace: "Calibri", color: C.mutedText, margin: 0,
    });
  }

  // ═══════════════════════════════════════════════════════════════════
  // SLIDE 4 — AUTOMOTIVE & LOGISTICS DEEP-DIVE
  // ═══════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };

    s.addText("Automotive & Logistics: AI Agents From Cockpit to Curbside", {
      x: 0.5, y: 0.3, w: 9, h: 0.65,
      fontSize: 24, fontFace: "Arial Black", color: C.darkText, bold: true, margin: 0,
    });
    s.addText("Representative use cases across Customer, Employee, and Code agent types", {
      x: 0.5, y: 0.95, w: 9, h: 0.3,
      fontSize: 12, fontFace: "Calibri", color: C.mutedText, italic: true,
    });

    // Table data
    const hdrOpts = (align = "center") => ({
      fill: { color: C.darkBg }, color: C.white, bold: true, fontSize: 9, align, valign: "middle",
    });
    const cellOpts = (align = "left", bold = false, color = C.bodyText) => ({
      fill: { color: C.white }, color, bold, fontSize: 8.5, align, valign: "middle",
    });
    const altCellOpts = (align = "left", bold = false, color = C.bodyText) => ({
      fill: { color: C.tableAlt }, color, bold, fontSize: 8.5, align, valign: "middle",
    });

    const rows = [
      // [Agent Type, Organization, Use Case, Key Metric]
      ["Customer", "Mercedes-Benz", "MBUX Virtual Assistant: natural driver conversations for navigation and POI", "Natural language in-car assistant"],
      ["Customer", "LUXGEN", "AI agent on LINE answers customer questions via Vertex AI", "Reduced CS workload by 30%"],
      ["Customer", "Volkswagen", "myVW app assistant for owner’s manuals; multimodal dashboard camera", "Gemini multimodal capabilities"],
      ["Customer", "UPS Capital", "DeliveryDefense: ML-based scoring of delivery success likelihood", "Data-driven delivery confidence"],
      ["Employee", "Toyota", "AI platform for factory workers to build and deploy ML models", "10,000+ man-hours/year saved"],
      ["Employee", "Uber", "AI agents summarize CS communications and surface prior context", "Improved CS rep effectiveness"],
      ["Employee", "Rivian", "Gemini in Workspace for research, learning, and skill acquisition", "Faster onboarding and deep research"],
      ["Code", "Renault (Ampere)", "Gemini Code Assist: understands company code base and conventions", "Developer productivity for EV software"],
    ];

    const tableData = [
      [
        { text: "Agent Type", options: hdrOpts("center") },
        { text: "Organization", options: hdrOpts("center") },
        { text: "Use Case", options: hdrOpts("left") },
        { text: "Key Metric / Detail", options: hdrOpts("left") },
      ],
      ...rows.map((r, i) => {
        const fn = i % 2 === 0 ? cellOpts : altCellOpts;
        return [
          { text: r[0], options: fn("center", true, C.primaryBlue) },
          { text: r[1], options: fn("center", true) },
          { text: r[2], options: fn("left") },
          { text: r[3], options: fn("left", false, C.emerald) },
        ];
      }),
    ];

    s.addTable(tableData, {
      x: 0.5, y: 1.4, w: 9,
      colW: [0.95, 1.35, 4.1, 2.6],
      border: { pt: 0.5, color: "CBD5E1" },
      rowH: [0.35, ...Array(8).fill(0.42)],
    });
  }

  // ═══════════════════════════════════════════════════════════════════
  // SLIDE 5 — MEASURABLE ROI HIGHLIGHTS
  // ═══════════════════════════════════════════════════════════════════
  {
    const s = pres.addSlide();
    s.background = { color: C.lightBg };

    s.addText("Quantified Impact: 500% ROI, 30% Workload Reduction, 10,000 Hours Saved", {
      x: 0.5, y: 0.3, w: 9, h: 0.65,
      fontSize: 22, fontFace: "Arial Black", color: C.darkText, bold: true, margin: 0,
    });
    s.addText("Production results from real enterprise deployments — not pilots", {
      x: 0.5, y: 0.95, w: 9, h: 0.3,
      fontSize: 12, fontFace: "Calibri", color: C.mutedText, italic: true,
    });

    const cards = [
      { num: "500%", label: "Anticipated ROI", company: "Mercari", desc: "Japan’s largest marketplace anticipates 500% ROI while reducing employee workloads by 20%", accent: C.emerald },
      { num: "30%", label: "Workload Reduction", company: "LUXGEN", desc: "Customer service agent workload reduced by 30% with Vertex AI chatbot on LINE", accent: C.skyBlue },
      { num: "10,000+", label: "Hours Saved / Year", company: "Toyota", desc: "Factory AI platform saved over 10,000 man-hours per year across manufacturing operations", accent: C.primaryBlue },
      { num: "6,000+", label: "Headlines in 29 Hours", company: "PODS / Tombras", desc: "Generated 6,000+ unique ad headlines across 299 NYC neighborhoods in just 29 hours", accent: C.amber },
    ];

    const cardW = 2.05;
    const gap = 0.2;
    const startX = 0.55;
    const cardY = 1.35;
    const cardH = 3.4;

    cards.forEach((c, i) => {
      const cx = startX + i * (cardW + gap);

      // Card background
      s.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: cardY, w: cardW, h: cardH,
        fill: { color: C.white }, shadow: mkShadow(),
      });
      // Left accent bar
      s.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: cardY, w: 0.06, h: cardH,
        fill: { color: c.accent },
      });
      // Big number
      s.addText(c.num, {
        x: cx + 0.2, y: cardY + 0.3, w: cardW - 0.35, h: 0.85,
        fontSize: 42, fontFace: "Arial Black", color: c.accent,
        bold: true, align: "left", valign: "middle", margin: 0,
      });
      // Label
      s.addText(c.label, {
        x: cx + 0.2, y: cardY + 1.2, w: cardW - 0.35, h: 0.35,
        fontSize: 13, fontFace: "Calibri", color: C.darkText, bold: true, align: "left", margin: 0,
      });
      // Company name
      s.addText(c.company, {
        x: cx + 0.2, y: cardY + 1.6, w: cardW - 0.35, h: 0.3,
