arguments.old_string:
const cards = [
  { num: "500%", label: "Anticipated ROI", company: "Mercari", desc: "Japan's largest marketplace anticipates 500% ROI while reducing employee workloads by 20%", accent: C.emerald },
  { num: "30%", label: "Workload Reduction", company: "LUXGEN", desc: "Customer service agent workload reduced by 30% with Vertex AI chatbot on LINE", accent: C.skyBlue },
  { num: "10,000+", label: "Hours Saved / Year", company: "Toyota", desc: "Factory AI platform saved over 10,000 man-hours per year across manufacturing operations", accent: C.primaryBlue },
  { num: "6,000+", label: "Headlines in 29 Hours", company: "PODS / Tombras", desc: "Generated 6,000+ unique ad headlines across 299 NYC neighborhoods in just 29 hours", accent: C.amber },
];

const cardW = 2.05;
const gap = 0.2;
const startX = 0.55;
const cardY = 1.35;
const cardH = 3.4;

cards.forEach((c, i) => {
  const cx = startX + i * (cardW + gap);

  // Card background
  s.addShape(pres.shapes.RECTANGLE, {
    x: cx, y: cardY, w: cardW, h: cardH,
    fill: { color: C.white }, shadow: mkShadow(),
  });
  // Left accent bar
  s.addShape(pres.shapes.RECTANGLE, {
    x: cx, y: cardY, w: 0.06, h: cardH,
    fill: { color: c.accent },
  });
  // Big number
  s.addText(c.num, {
    x: cx + 0.2, y: cardY + 0.3, w: cardW - 0.35, h: 0.85,
    fontSize: 42, fontFace: "Arial Black", color: c.accent,
    bold: true, align: "left", valign: "middle", margin: 0,
  });
  // Label
  s.addText(c.label, {
    x: cx + 0.2, y: cardY + 1.2, w: cardW - 0.35, h: 0.35,
    fontSize: 13, fontFace: "Calibri", color: C.darkText, bold: true, align: "left", margin: 0,
  });
  // Company name
  s.addText(c.company, {
    x: cx + 0.2, y: cardY + 1.6, w: cardW - 0.35, h: 0.3,
    fontSize: 11, fontFace: "Calibri", color: C.primaryBlue, bold: true, align: "left", margin: 0,
  });
  // Description
  s.addText(c.desc, {
    x: cx + 0.2, y: cardY + 1.95, w: cardW - 0.35, h: 1.2,
    fontSize: 9, fontFace: "Calibri", color: C.bodyText, align: "left", valign: "top",
  });
});

