const colW = 2.85;
const colGap = 0.22;
const colStartX = 0.5;
const colY = 1.4;

cols.forEach((col, i) => {
  const cx = colStartX + i * (colW + colGap);

  // Column card
  s.addShape(pres.shapes.RECTANGLE, {
    x: cx, y: colY, w: colW, h: 3.8,
    fill: { color: C.white }, shadow: mkShadow(),
  });

  // Icon circle
  const iconSize = 0.55;
  const iconX = cx + (colW - iconSize) / 2;
  s.addShape(pres.shapes.OVAL, {
    x: iconX, y: colY + 0.25, w: iconSize, h: iconSize,
    fill: { color: col.iconBg },
  });
  s.addImage({
    data: col.icon,
    x: iconX + 0.12, y: colY + 0.37, w: 0.31, h: 0.31,
  });

  // Title
  s.addText(col.title, {
    x: cx + 0.2, y: colY + 0.95, w: colW - 0.4, h: 0.55,
    fontSize: 14, fontFace: "Arial Black", color: C.darkText,
    bold: true, align: "center", valign: "top", margin: 0,
  });

  // Tag
  s.addText(col.tag, {
    x: cx + 0.2, y: colY + 1.5, w: colW - 0.4, h: 0.25,
    fontSize: 9, fontFace: "Calibri", color: col.iconBg, bold: true, align: "center", margin: 0,
  });

  // Description
  s.addText(col.desc, {
    x: cx + 0.2, y: colY + 1.8, w: colW - 0.4, h: 0.85,
    fontSize: 9, fontFace: "Calibri", color: C.bodyText, align: "left", valign: "top",
  });

  // Company examples
  const companyText = col.companies.map((c, j) => ({
    text: c,
    options: {
      bullet: true,
      breakLine: j < col.companies.length - 1,
      fontSize: 8.5,
      color: C.darkText,
    },
  }));
  s.addText(companyText, {
    x: cx + 0.2, y: colY + 2.7, w: colW - 0.4, h: 1.0,
    fontFace: "Calibri", valign: "top",
  });
});

